import { test } from "node:test";
import assert from "node:assert/strict";
import { capitalizeWords } from "./solution.mjs";

test("words", () => {
  assert.equal(capitalizeWords("quarterly sales report"), "Quarterly Sales Report");
});

test("keeps the rest", () => {
  assert.equal(capitalizeWords("iPhone and macOS"), "IPhone And MacOS");
});

test("empty", () => {
  assert.equal(capitalizeWords(""), "");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { range } from "./solution.mjs";

test("default step", () => {
  assert.deepEqual(range(2, 6), [2, 3, 4, 5]);
});

test("step", () => {
  assert.deepEqual(range(0, 10, 3), [0, 3, 6, 9]);
});

test("empty", () => {
  assert.deepEqual(range(5, 5), []);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { uniqueSorted } from "./solution.mjs";

test("numeric order", () => {
  assert.deepEqual(uniqueSorted([10, 2, 33, 2, 10, 1]), [1, 2, 10, 33]);
});

test("input untouched", () => {
  const input = [3, 1, 3];
  uniqueSorted(input);
  assert.deepEqual(input, [3, 1, 3]);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { groupBy } from "./solution.mjs";

test("groups", () => {
  const a = { team: "ops", n: 1 }, b = { team: "dev", n: 2 }, c = { team: "ops", n: 3 };
  assert.deepEqual(groupBy([a, b, c], "team"), { ops: [a, c], dev: [b] });
});

test("empty", () => {
  assert.deepEqual(groupBy([], "team"), {});
});

