import { test } from "node:test";
import assert from "node:assert/strict";
import { istAusgeglichen } from "./solution.mjs";

test("ausgeglichen", () => {
  assert.equal(istAusgeglichen("f(a[0], {b: 1})"), true);
  assert.equal(istAusgeglichen(""), true);
});

test("nicht ausgeglichen", () => {
  assert.equal(istAusgeglichen("(]"), false);
  assert.equal(istAusgeglichen("(("), false);
  assert.equal(istAusgeglichen("())"), false);
});
